const row = items[0]?.json ?? {};

const safe = (value, fallback = '') => String(value ?? fallback).trim();
const compactObject = (value) => value && typeof value === 'object' ? value : {};
const aiEnabled = String($env.AI_LEAD_ASSISTANT_ENABLED || 'false').toLowerCase() === 'true';
const provider = safe($env.AI_PROVIDER, safe($env.OPENAI_API_KEY ? 'openai' : 'nvidia')).toLowerCase();
const defaultBaseUrl = provider === 'nvidia'
  ? 'https://integrate.api.nvidia.com/v1'
  : provider === 'ollama'
    ? 'http://host.docker.internal:11434/v1'
    : 'https://api.openai.com/v1';
const baseUrl = safe($env.AI_BASE_URL, defaultBaseUrl).replace(/\/+$/, '');
const apiMode = safe($env.AI_API_MODE, 'chat_completions').toLowerCase() === 'responses' ? 'responses' : 'chat_completions';
const model = safe($env.AI_MODEL, safe($env.OPENAI_MODEL, provider === 'nvidia' ? 'minimaxai/minimax-m2.5' : 'gpt-5.4-mini'));
const apiKey = safe($env.AI_API_KEY, safe($env.OPENAI_API_KEY));
const apiKeyRequired = String($env.AI_API_KEY_REQUIRED || (provider === 'ollama' ? 'false' : 'true')).toLowerCase() === 'true';

const currentContext = {
  message_current: safe(row.message_current, safe(row.text_body)),
  message_type: safe(row.message_type, 'text'),
  conversation_status: safe(row.conversation_status_code, safe(row.conversation_status)),
  current_step: safe(row.current_step),
  existing_fields: {
    service: safe(row.service),
    city: safe(row.city),
    requirement: safe(row.requirement),
  },
  previous_lead: compactObject(row.previous_lead),
  recent_messages: Array.isArray(row.recent_messages) ? row.recent_messages.slice(-8) : [],
};

const responseSchema = {
  "type": "object",
  "additionalProperties": false,
  "required": [
    "intent",
    "lead_quality",
    "service",
    "city",
    "requirement",
    "missing_fields",
    "should_create_lead",
    "needs_confirmation",
    "confidence",
    "reply_text",
    "clickup_summary"
  ],
  "properties": {
    "intent": {
      "type": "string",
      "enum": [
        "greeting",
        "quote_request",
        "provide_info",
        "correction",
        "confirmation_yes",
        "confirmation_no",
        "new_request",
        "continue_previous",
        "irrelevant",
        "unknown"
      ]
    },
    "lead_quality": {
      "type": "string",
      "enum": [
        "none",
        "low",
        "medium",
        "high"
      ]
    },
    "service": {
      "type": "string"
    },
    "city": {
      "type": "string"
    },
    "requirement": {
      "type": "string"
    },
    "missing_fields": {
      "type": "array",
      "items": {
        "type": "string",
        "enum": [
          "service",
          "city",
          "requirement",
          "confirmation"
        ]
      }
    },
    "should_create_lead": {
      "type": "boolean"
    },
    "needs_confirmation": {
      "type": "boolean"
    },
    "confidence": {
      "type": "number",
      "minimum": 0,
      "maximum": 1
    },
    "reply_text": {
      "type": "string"
    },
    "clickup_summary": {
      "type": "string"
    }
  }
};

if (!aiEnabled || (apiKeyRequired && !apiKey)) {
  return [
    {
      json: {
        ai_skipped: true,
        ai_skip_reason: !aiEnabled ? 'disabled' : 'missing_ai_api_key',
        ai_provider: provider,
        ai_model: model,
        ai_base_url: baseUrl,
        ai_api_mode: apiMode,
        ai_context: currentContext,
        response_schema: responseSchema,
      },
    },
  ];
}

const systemPrompt = [
  'Eres AI - Lead Qualification Assistant para un CRM por WhatsApp.',
  'Tu tarea es extraer y recomendar, no decidir ni modificar estado.',
  'Devuelve solo datos compatibles con el JSON Schema.',
  'Reglas de negocio:',
  '- No recomiendes crear lead si falta servicio, ciudad, requerimiento concreto o confirmacion.',
  '- Si hay baja confianza, pide aclaracion y marca needs_confirmation=true.',
  '- Usa espanol claro y breve para reply_text.',
  '- Mantén service, city y requirement vacios si no hay evidencia suficiente.',
  '- No inventes datos. Puedes conservar datos existentes si el mensaje no los contradice.',
].join('\n');

const userPrompt = JSON.stringify(currentContext, null, 2);
const messages = [
  { role: 'system', content: systemPrompt },
  { role: 'user', content: userPrompt },
];
const responseFormat = {
  type: 'json_schema',
  json_schema: {
    name: 'lead_qualification_result',
    strict: true,
    schema: responseSchema,
  },
};
const responsesFormat = {
  type: 'json_schema',
  name: 'lead_qualification_result',
  strict: true,
  schema: responseSchema,
};
const aiRequest = apiMode === 'chat_completions'
  ? {
      model,
      messages,
      response_format: responseFormat,
      max_tokens: 900,
      temperature: 0.1,
    }
  : {
      model,
      input: messages,
      text: {
        format: responsesFormat,
      },
      max_output_tokens: 900,
    };

return [
  {
    json: {
      ai_skipped: false,
      ai_provider: provider,
      ai_model: model,
      ai_base_url: baseUrl,
      ai_api_mode: apiMode,
      ai_context: currentContext,
      response_schema: responseSchema,
      ai_request: aiRequest,
      ai_request_path: apiMode === 'chat_completions' ? '/chat/completions' : '/responses',
    },
  },
];

const row = items[0]?.json ?? {};

if (row.ai_skipped) {
  return [{ json: { ...row, ai_status_code: null, ai_response: null, ai_retry_attempts: 0 } }];
}

const retryableStatusCodes = new Set([408, 409, 425, 429, 500, 502, 503, 504]);
const maxAttempts = Number($env.EXTERNAL_HTTP_MAX_ATTEMPTS || 4);
const baseDelayMs = Number($env.EXTERNAL_HTTP_RETRY_BASE_MS || 1000);
const maxDelayMs = Number($env.EXTERNAL_HTTP_RETRY_MAX_MS || 10000);
const sleep = (ms) => new Promise((resolve) => setTimeout(resolve, ms));
const retryDelay = (attempt) => Math.min(maxDelayMs, baseDelayMs * Math.pow(2, attempt - 1)) + Math.floor(Math.random() * 250);
const safe = (value, fallback = '') => String(value ?? fallback).trim();
const baseUrl = safe(row.ai_base_url, 'https://api.openai.com/v1').replace(/\/+$/, '');
const path = safe(row.ai_request_path, row.ai_api_mode === 'chat_completions' ? '/chat/completions' : '/responses');
const url = baseUrl + (path.startsWith('/') ? path : '/' + path);
const apiKey = safe($env.AI_API_KEY, safe($env.OPENAI_API_KEY));

let lastError = null;

for (let attempt = 1; attempt <= maxAttempts; attempt += 1) {
  try {
    const headers = { 'Content-Type': 'application/json' };
    if (apiKey) headers.Authorization = 'Bearer ' + apiKey;

    const response = await helpers.httpRequest({
      method: 'POST',
      url,
      headers,
      body: row.ai_request,
      json: true,
      returnFullResponse: true,
      ignoreHttpStatusErrors: true,
    });

    const statusCode = Number(response.statusCode || 0);
    const shouldRetry = retryableStatusCodes.has(statusCode) && attempt < maxAttempts;
    if (!shouldRetry) {
      return [
        {
          json: {
            ...row,
            ai_status_code: statusCode,
            ai_response: response.body || {},
            ai_retry_attempts: attempt,
            ai_retry_exhausted: retryableStatusCodes.has(statusCode) && attempt >= maxAttempts,
            ai_retry_last_error: null,
          },
        },
      ];
    }
  } catch (error) {
    lastError = error;
    if (attempt >= maxAttempts) {
      return [
        {
          json: {
            ...row,
            ai_status_code: 0,
            ai_response: { error: { message: error.message } },
            ai_retry_attempts: attempt,
            ai_retry_exhausted: true,
            ai_retry_last_error: error.message,
          },
        },
      ];
    }
  }

  await sleep(retryDelay(attempt));
}

return [{ json: { ...row, ai_status_code: 0, ai_response: { error: { message: lastError?.message || 'AI provider retry exhausted' } }, ai_retry_attempts: maxAttempts, ai_retry_exhausted: true, ai_retry_last_error: lastError?.message || null } }];

const row = items[0]?.json ?? {};

const safe = (value, fallback = '') => String(value ?? fallback).trim();
const clampConfidence = (value) => {
  const number = Number(value);
  if (!Number.isFinite(number)) return 0;
  return Math.max(0, Math.min(1, number));
};
const extractTextFromContent = (content) => {
  if (typeof content === 'string') return content;
  if (!Array.isArray(content)) return '';
  return content
    .map((entry) => {
      if (typeof entry === 'string') return entry;
      if (!entry || typeof entry !== 'object') return '';
      return safe(entry.text, safe(entry.output_text));
    })
    .filter(Boolean)
    .join('\n');
};
const extractOutputText = (response) => {
  if (!response || typeof response !== 'object') return '';
  if (typeof response.output_text === 'string') return response.output_text;

  const output = Array.isArray(response.output) ? response.output : [];
  const responseParts = [];
  for (const item of output) {
    const content = Array.isArray(item.content) ? item.content : [];
    for (const entry of content) {
      if (typeof entry.text === 'string') responseParts.push(entry.text);
      if (typeof entry.output_text === 'string') responseParts.push(entry.output_text);
    }
  }
  if (responseParts.length) return responseParts.join('\n').trim();

  const choices = Array.isArray(response.choices) ? response.choices : [];
  const chatParts = [];
  for (const choice of choices) {
    if (typeof choice.text === 'string') chatParts.push(choice.text);
    const messageContent = choice.message?.content;
    const text = extractTextFromContent(messageContent);
    if (text) chatParts.push(text);
  }
  return chatParts.join('\n').trim();
};

const existing = row.ai_context?.existing_fields || {};
const fallbackMissing = ['service', 'city', 'requirement'].filter((field) => !safe(existing[field]));
const skippedResult = {
  intent: 'unknown',
  lead_quality: 'none',
  service: safe(existing.service),
  city: safe(existing.city),
  requirement: safe(existing.requirement),
  missing_fields: fallbackMissing,
  should_create_lead: false,
  needs_confirmation: true,
  confidence: 0,
  reply_text: '',
  clickup_summary: '',
};

let parsed = skippedResult;
let parseError = null;
const statusCode = Number(row.ai_status_code || 0);

if (!row.ai_skipped && statusCode >= 200 && statusCode < 300) {
  const outputText = extractOutputText(row.ai_response);
  try {
    parsed = JSON.parse(outputText);
  } catch (error) {
    parseError = error.message;
  }
}

const allowedIntent = new Set(['greeting', 'quote_request', 'provide_info', 'correction', 'confirmation_yes', 'confirmation_no', 'new_request', 'continue_previous', 'irrelevant', 'unknown']);
const allowedQuality = new Set(['none', 'low', 'medium', 'high']);
const allowedMissing = new Set(['service', 'city', 'requirement', 'confirmation']);

const service = safe(parsed.service, safe(existing.service));
const city = safe(parsed.city, safe(existing.city));
const requirement = safe(parsed.requirement, safe(existing.requirement));
const missingFields = Array.isArray(parsed.missing_fields)
  ? parsed.missing_fields.filter((field) => allowedMissing.has(field))
  : ['service', 'city', 'requirement'].filter((field) => !safe({ service, city, requirement }[field]));
const confidence = clampConfidence(parsed.confidence);
const hasRequiredLeadFields = Boolean(service && city && requirement);
const modelShouldCreateLead = Boolean(parsed.should_create_lead);
const guardedShouldCreateLead = modelShouldCreateLead && hasRequiredLeadFields && !missingFields.includes('confirmation') && confidence >= 0.75;

return [
  {
    json: {
      ai_skipped: Boolean(row.ai_skipped),
      ai_skip_reason: row.ai_skip_reason || null,
      ai_provider: row.ai_provider || null,
      ai_model: row.ai_model || null,
      ai_api_mode: row.ai_api_mode || null,
      ai_status_code: row.ai_status_code || null,
      ai_retry_attempts: row.ai_retry_attempts || 0,
      ai_retry_exhausted: Boolean(row.ai_retry_exhausted),
      ai_parse_error: parseError,
      intent: allowedIntent.has(parsed.intent) ? parsed.intent : 'unknown',
      lead_quality: allowedQuality.has(parsed.lead_quality) ? parsed.lead_quality : 'none',
      service,
      city,
      requirement,
      missing_fields: missingFields,
      should_create_lead: guardedShouldCreateLead,
      model_should_create_lead_raw: modelShouldCreateLead,
      needs_confirmation: Boolean(parsed.needs_confirmation || !guardedShouldCreateLead),
      confidence,
      reply_text: safe(parsed.reply_text),
      clickup_summary: safe(parsed.clickup_summary),
      metadata_json: JSON.stringify({
        provider: row.ai_provider || null,
        model: row.ai_model || null,
        api_mode: row.ai_api_mode || null,
        status_code: row.ai_status_code || null,
        retry_attempts: row.ai_retry_attempts || 0,
        retry_exhausted: Boolean(row.ai_retry_exhausted),
        parse_error: parseError,
        model_should_create_lead_raw: modelShouldCreateLead,
        guardrail_has_required_lead_fields: hasRequiredLeadFields,
      }),
    },
  },
];
